/* Proposed Sales ownership; source provenance remains separate from editable local values. */
(function(){
const rows=[
 ['valuation_adult_female_rate','Adult female valuation rate','currency',600,'INR/kg'],['valuation_adult_female_weight','Adult female assumed weight','weight',40,'kg'],
 ['valuation_adult_male_rate','Adult male / buck valuation rate','currency',500,'INR/kg'],['valuation_adult_male_weight','Adult male / buck assumed weight','weight',60,'kg'],
 ['valuation_k0_rate','K0 valuation rate','currency',500,'INR/kg'],['valuation_k0_weight','K0 assumed weight','weight',3,'kg'],
 ['valuation_k1_rate','K1 valuation rate','currency',500,'INR/kg'],['valuation_k1_weight','K1 assumed weight','weight',3,'kg'],
 ['valuation_k2_rate','K2 valuation rate','currency',500,'INR/kg'],['valuation_k2_weight','K2 assumed weight','weight',8,'kg'],
 ['valuation_k3_rate','K3 valuation rate','currency',500,'INR/kg'],['valuation_k3_weight','K3 assumed weight','weight',15,'kg']
];
function seed(){ensureTypedConfig();for(const [key,name,valueType,value,unit] of rows)if(!state.items.some(i=>i.configKey===key))state.items.push({id:'config-'+key,name,itemKind:'config_value',configKey:key,valueType,value,unit,currency:valueType==='currency'?'INR':'',module:'Common',sourceOwner:'Sales',sourceKind:'hardcoded_source',sourceValue:value,sourceRef:'backend/internal/sales/adapters/postgres/overview_repository.go:617–625',scope:'Sales-owned valuation assumption, shared for reporting; not a recorded transaction',purpose:'Sales valuation',description:'Proposed editable replacement for an observed code constant.',categoryId:'category-shared-configuration',subcategoryId:'subcategory-shared-settings',shares:['Sales','Weighing'],active:true,revision:1});for(const key of ['reporting_weight_30','reporting_weight_35']){const i=state.items.find(i=>i.configKey===key);if(i)i.sourceOwner='Sales';}}
seed();
for(const key of ['reporting_weight_30','reporting_weight_35','valuation_fattening_rate',...rows.map(r=>r[0])])consumerBoundPages[key]=[...new Set([...(consumerBoundPages[key]||[]),'Sales Config',...(rows.some(r=>r[0]===key)?['Farm value']:[])])];
const previousUsages=itemUsages;
itemUsages=function(id){const usages=previousUsages(id),item=itemById(id);if(!item||!['reporting_weight_30','reporting_weight_35','valuation_fattening_rate',...rows.map(r=>r[0])].includes(item.configKey))return usages;for(const title of consumerBoundPages[item.configKey]||[]){const module=title==='ADG Analytics'?'Weighing':'Sales';if(!usages.some(u=>u.kind==='Consumer preview'&&u.title===title))usages.push({title,module,kind:'Consumer preview',nodeId:'consumer:'+title,nodeLabel:item.name,nodeType:'Shared setting on page',activeDraft:false});}return usages;};
const previousOpenUsage=openItemUsage;
openItemUsage=function(id,index){const usage=itemUsages(id).filter(u=>canEdit()||u.kind.startsWith('Published'))[index];if(usage?.kind==='Consumer preview'){closeModal();productionNavigate(usage.module,usage.title);return;}return previousOpenUsage(id,index);};
const previous=window.renderConsumerSurface;window.renderConsumerSurface=function(module,label){const result=previous(module,label);if(result&&label==='Sales Config'){$('#content').insertAdjacentHTML('beforeend',`<section class="card"><h2>Rates, assumed weights and reporting thresholds</h2><p>Sales owns these proposed settings. Weighing and Farm value read the same saved values. Rates used for valuation, sale eligibility and actual recorded prices are labelled separately.</p><div class="tablewrap"><table><thead><tr><th>Setting</th><th>Current local value</th><th>Action</th></tr></thead><tbody>${['reporting_weight_30','reporting_weight_35','valuation_fattening_rate',...rows.map(r=>r[0])].map(key=>{const i=consumerAllowed(key)?configValueByKey(key):null;return `<tr><td>${esc(i?.name||key)}</td><td>${esc(String(i?.value??'Unavailable'))} ${esc(i?.unit||'')}</td><td>${consumerConfigLink(key,'Edit setting')}</td></tr>`;}).join('')}</tbody></table></div><p class="muted">The observed application fixes these values in code. Editing this prototype only saves a local proposal; it does not update production.</p></section>`);}return result;};
})();
